function uniqueBy(items, keyOf) {
  const seen = new Set();
  const result = [];
  for (const item of items) {
    const key = keyOf(item);
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(item);
  }
  return result;
}

module.exports = { uniqueBy };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { uniqueBy } = require('../src/solution.cjs');

test('keeps the first item for each duplicate key, in input order', () => {
  const items = [
    { id: 'b', n: 1 },
    { id: 'a', n: 2 },
    { id: 'b', n: 3 },
    { id: 'c', n: 4 },
    { id: 'a', n: 5 },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.id), [
    { id: 'b', n: 1 },
    { id: 'a', n: 2 },
    { id: 'c', n: 4 },
  ]);
});

test('treats number 1 and string "1" as different keys', () => {
  const items = [
    { k: 1, v: 'num' },
    { k: '1', v: 'str' },
    { k: 1, v: 'num-again' },
    { k: '1', v: 'str-again' },
  ];
  assert.deepEqual(uniqueBy(items, (x) => x.k), [
    { k: 1, v: 'num' },
    { k: '1', v: 'str' },
  ]);
});

test('handles mixed string and number keys', () => {
  const keys = [2, 'x', 2, '2', 'x', 0, '0', 0];
  assert.deepEqual(uniqueBy(keys, (x) => x), [2, 'x', '2', 0, '0']);
});

test('treats "__proto__" and other prototype-like names as ordinary keys', () => {
  const keys = ['__proto__', 'constructor', '__proto__', 'toString', 'constructor'];
  assert.deepEqual(uniqueBy(keys, (x) => x), ['__proto__', 'constructor', 'toString']);
});

test('returns [] for empty input', () => {
  assert.deepEqual(uniqueBy([], () => 'anything'), []);
});

test('returns a new array and does not mutate the input', () => {
  const items = [1, 1, 2];
  const snapshot = [...items];
  const result = uniqueBy(items, (x) => x);
  assert.notEqual(result, items);
  assert.deepEqual(result, [1, 2]);
  assert.deepEqual(items, snapshot);
});

test('calls keyOf once per item in order', () => {
  const calls = [];
  uniqueBy(['a', 'b', 'a'], (x) => {
    calls.push(x);
    return x;
  });
  assert.deepEqual(calls, ['a', 'b', 'a']);
});

