        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_unsorted_input_is_sorted_and_merged(self):
        self.assertEqual(
            merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_containment_in_either_order(self):
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates_collapse(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_degenerate_point_intervals(self):
        self.assertEqual(
            merge_intervals([[3, 3], [1, 1], [3, 3], [2, 2]]),
            [[1, 1], [2, 2], [3, 3]],
        )

    def test_point_touching_interval_merges(self):
        self.assertEqual(merge_intervals([[1, 4], [4, 4]]), [[1, 4]])

    def test_chain_of_overlaps_merges_transitively(self):
        self.assertEqual(
            merge_intervals([[1, 4], [3, 6], [5, 8], [7, 9]]), [[1, 9]]
        )

    def test_negative_coordinates(self):
        self.assertEqual(
            merge_intervals([[-5, -2], [-3, 1], [4, 6], [-10, -9]]),
            [[-10, -9], [-5, 1], [4, 6]],
        )

    def test_negative_gap_stays_separate(self):
        self.assertEqual(merge_intervals([[-4, -2], [-1, 0]]), [[-4, -2], [-1, 0]])

    def test_input_is_not_mutated(self):
        intervals = [[8, 10], [1, 3], [2, 6], [2, 3]]
        snapshot = copy.deepcopy(intervals)
        merge_intervals(intervals)
        self.assertEqual(intervals, snapshot)

    def test_output_does_not_alias_input_pairs(self):
        intervals = [[1, 2], [5, 6]]
        result = merge_intervals(intervals)
        result[0][1] = 99
        self.assertEqual(intervals, [[1, 2], [5, 6]])

    def test_output_is_sorted_and_nonoverlapping(self):
        intervals = [[5, 9], [0, 2], [2, 4], [8, 12], [-3, -3], [11, 11]]
        result = merge_intervals(intervals)
        for start, end in result:
            self.assertLessEqual(start, end)
        for (_, prev_end), (next_start, _) in zip(result, result[1:]):
            self.assertLess(prev_end, next_start)


