'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { TTLCache } = require('../src/solution.cjs');

function fakeClock(start = 1000) {
  let t = start;
  return {
    now: () => t,
    advance: (ms) => {
      t += ms;
    },
    set: (ms) => {
      t = ms;
    },
  };
}

test('returns a value before its expiry', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'x', 100);
  clock.advance(99);
  assert.equal(cache.get('a'), 'x');
});

test('returns undefined exactly at the expiry instant and removes the entry', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'x', 100);
  clock.advance(100);
  assert.equal(cache.get('a'), undefined);
  clock.set(1000);
  assert.equal(cache.get('a'), undefined);
});

test('missing keys return undefined', () => {
  const cache = new TTLCache(fakeClock().now);
  assert.equal(cache.get('nope'), undefined);
});

test('a later set resets the expiry', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'first', 100);
  clock.advance(60);
  cache.set('a', 'second', 100);
  clock.advance(60);
  assert.equal(cache.get('a'), 'second');
  clock.advance(40);
  assert.equal(cache.get('a'), undefined);
});

test('a later set after expiry stores a fresh entry', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'old', 10);
  clock.advance(10);
  assert.equal(cache.get('a'), undefined);
  cache.set('a', 'new', 50);
  clock.advance(49);
  assert.equal(cache.get('a'), 'new');
});

test('falsy values false, 0 and null are returned as stored', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('f', false, 100);
  cache.set('z', 0, 100);
  cache.set('n', null, 100);
  assert.equal(cache.get('f'), false);
  assert.equal(cache.get('z'), 0);
  assert.equal(cache.get('n'), null);
});

test('ttl of 0 expires at the same instant it was set', () => {
  const clock = fakeClock();
  const cache = new TTLCache(clock.now);
  cache.set('a', 'x', 0);
  assert.equal(cache.get('a'), undefined);
});

test('expiry is computed from the clock at set time', () => {
  const clock = fakeClock(500);
