function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function controlledFn() {
  const calls = [];
  const fn = (item) => {
    const call = { item, ...deferred() };
    calls.push(call);
    return call.promise;
  };
  return { fn, calls };
}

const flush = () => new Promise((resolve) => setImmediate(resolve));

