  const sleep = () => new Promise((resolve) => {
    resolveSleep = resolve;
  });
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls === 1) throw new Error('first');
    return 'second';
  };

  const pending = retry(operation, { attempts: 2, delayMs: 1, sleep });
  await Promise.resolve();
  assert.equal(calls, 1);

  resolveSleep();
  assert.equal(await pending, 'second');
  assert.equal(calls, 2);
});

test('passes each rejected error to shouldRetry', async () => {
  const { sleep } = fakeSleep();
  const errors = [new Error('a'), new Error('b')];
  let calls = 0;
  const seen = [];

  await assert.rejects(
    retry(async () => {
      const error = errors[calls];
      calls += 1;
      throw error;
    }, {
      attempts: 2,
      sleep,
      shouldRetry: (error) => {
        seen.push(error);
        return true;
      },
    }),
    (thrown) => thrown === errors[1],
  );
  assert.deepEqual(seen, [errors[0]]);
});

test('rejects with RangeError for invalid attempts', async () => {
  const invalid = [0, -1, 1.5, NaN, Infinity, '3', null, undefined];
  for (const attempts of invalid) {
    let called = false;
    await assert.rejects(
      retry(async () => {
        called = true;
      }, { attempts }),
      RangeError,
      `attempts=${String(attempts)}`,
    );
    assert.equal(called, false);
  }
});

async function retry(operation, { attempts, delayMs, sleep, shouldRetry }) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

