const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function retry(
  operation,
  { attempts, delayMs = 0, sleep = defaultSleep, shouldRetry = () => true } = {},
) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError(`attempts must be a positive integer, got ${String(attempts)}`);
  }

  for (let attempt = 1; ; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(delayMs);
    }
  }
}

module.exports = { retry };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('../src/solution.cjs');

function fakeSleep() {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  return { sleep, delays };
}

function failTimes(count, value) {
  let calls = 0;
  const operation = async () => {
    calls += 1;
    if (calls <= count) {
      throw new Error(`failure ${calls}`);
    }
    return value;
  };
  return { operation, calls: () => calls };
}

test('returns the first value without sleeping when the operation succeeds', async () => {
  const { sleep, delays } = fakeSleep();
  const operation = failTimes(0, 'ok');

  assert.equal(await retry(operation.operation, { attempts: 3, delayMs: 50, sleep }), 'ok');
  assert.equal(operation.calls(), 1);
  assert.deepEqual(delays, []);
});

test('retries until success and sleeps once between each attempt', async () => {
  const { sleep, delays } = fakeSleep();
  const operation = failTimes(2, 'third time');

  assert.equal(await retry(operation.operation, { attempts: 5, delayMs: 50, sleep }), 'third time');
  assert.equal(operation.calls(), 3);
  assert.deepEqual(delays, [50, 50]);
});

test('after exhaustion throws the last error object unchanged', async () => {
  const { sleep, delays } = fakeSleep();
  const errors = [];
  let calls = 0;
  const operation = async () => {
    calls += 1;
    const error = new Error(`attempt ${calls}`);
    error.attempt = calls;
    errors.push(error);
    throw error;
  };

  await assert.rejects(
    retry(operation, { attempts: 3, delayMs: 10, sleep }),
    (error) => error === errors[2] && error.attempt === 3,
  );
  assert.equal(calls, 3);
  assert.deepEqual(delays, [10, 10]);
});

test('does not sleep after the final failed attempt', async () => {
  const { sleep, delays } = fakeSleep();
  const operation = failTimes(Infinity, 'never');

  await assert.rejects(retry(operation.operation, { attempts: 1, delayMs: 99, sleep }));
  assert.equal(operation.calls(), 1);
  assert.deepEqual(delays, []);
});

test('stops immediately when shouldRetry returns false and rethrows that error', async () => {
  const { sleep, delays } = fakeSleep();
  const fatal = new Error('fatal');
  const seen = [];
  let calls = 0;
  const operation = async () => {
    calls += 1;
    throw calls === 1 ? new Error('transient') : fatal;
  };
  const shouldRetry = (error) => {
    seen.push(error.message);
    return error.message === 'transient';
  };

  await assert.rejects(
    retry(operation, { attempts: 5, delayMs: 20, sleep, shouldRetry }),
    (error) => error === fatal,
  );
  assert.equal(calls, 2);
  assert.deepEqual(seen, ['transient', 'fatal']);
  assert.deepEqual(delays, [20]);
});

test('waits for sleep to resolve before calling the operation again', async () => {
  const events = [];
  let releaseSleep;
  const sleep = (ms) => {
    events.push(`sleep ${ms}`);
    return new Promise((resolve) => {
      releaseSleep = resolve;
    });
  };
  let calls = 0;
  const operation = async () => {
    calls += 1;
    events.push(`call ${calls}`);
    if (calls === 1) throw new Error('first');
    return 'done';
  };

  const pending = retry(operation, { attempts: 2, delayMs: 5, sleep });
  await Promise.resolve();
  await Promise.resolve();
  assert.deepEqual(events, ['call 1', 'sleep 5']);

  releaseSleep();
  assert.equal(await pending, 'done');
  assert.deepEqual(events, ['call 1', 'sleep 5', 'call 2']);
});

test('a single attempt calls the operation once and never sleeps', async () => {
  const { sleep, delays } = fakeSleep();
  const operation = failTimes(1, 'unused');

  await assert.rejects(retry(operation.operation, { attempts: 1, sleep }), /failure 1/);
  assert.equal(operation.calls(), 1);
  assert.deepEqual(delays, []);
});

test('passes delayMs of zero to sleep by default', async () => {
  const { sleep, delays } = fakeSleep();
  const operation = failTimes(1, 'ok');

  assert.equal(await retry(operation.operation, { attempts: 2, sleep }), 'ok');
  assert.deepEqual(delays, [0]);
});

test('rejects invalid attempts with RangeError without calling the operation', async () => {
  for (const attempts of [0, -1, 1.5, NaN, Infinity, '3', undefined, null]) {
    let calls = 0;
    const operation = async () => {
      calls += 1;
    };
    await assert.rejects(retry(operation, { attempts }), RangeError);
    assert.equal(calls, 0);
  }
});

