_MIN_LIMIT = 1
_MAX_LIMIT = 100


def _escape_like(text):
    return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def search(conn, name_prefix, limit):
    if not isinstance(name_prefix, str):
        raise TypeError("name_prefix must be a str")
    if type(limit) is not int:
        raise ValueError("limit must be an int")
    limit = min(max(limit, _MIN_LIMIT), _MAX_LIMIT)
    pattern = _escape_like(name_prefix) + "%"
    return conn.execute(
        r"SELECT id, name FROM users WHERE name LIKE ? ESCAPE '\' ORDER BY name, id LIMIT ?",
        (pattern, limit),
    ).fetchall()

