import csv
import io
import re

_HEADER = ["name", "age"]
_AGE_PATTERN = re.compile(r"[0-9]+")
_MAX_AGE = 130


def read_people(text):
    try:
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as exc:
        raise ValueError(f"invalid CSV: {exc}") from exc

    if not rows or rows[0] != _HEADER:
        raise ValueError("header must be exactly name,age")

    people = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
        name, age_text = row
        if not _AGE_PATTERN.fullmatch(age_text):
            raise ValueError(f"invalid age: {age_text!r}")
        age = int(age_text)
        if age > _MAX_AGE:
            raise ValueError(f"age out of range 0..{_MAX_AGE}: {age}")
        people.append({"name": name, "age": age})
    return people

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from solution import read_people  # noqa: E402


class ReadPeopleTests(unittest.TestCase):
    def test_parses_rows_in_order(self):
        self.assertEqual(
            read_people("name,age\nAlice,30\nBob,4\n"),
            [{"name": "Alice", "age": 30}, {"name": "Bob", "age": 4}],
        )

    def test_header_only_returns_empty_list(self):
        self.assertEqual(read_people("name,age\n"), [])
        self.assertEqual(read_people("name,age"), [])

    def test_crlf_line_endings(self):
        self.assertEqual(
            read_people("name,age\r\nAlice,30\r\n"),
            [{"name": "Alice", "age": 30}],
        )

    def test_quoted_name_with_comma(self):
        self.assertEqual(
            read_people('name,age\n"Doe, Jane",41\n'),
            [{"name": "Doe, Jane", "age": 41}],
        )

    def test_quoted_name_with_embedded_newline(self):
        self.assertEqual(
            read_people('name,age\n"Line one\nLine two",20\nBob,3\n'),
            [
                {"name": "Line one\nLine two", "age": 20},
                {"name": "Bob", "age": 3},
            ],
        )

    def test_quoted_name_with_embedded_crlf_is_preserved(self):
        self.assertEqual(
            read_people('name,age\r\n"a\r\nb",5\r\n'),
            [{"name": "a\r\nb", "age": 5}],
        )

    def test_doubled_quotes_inside_quoted_field(self):
        self.assertEqual(
            read_people('name,age\n"He said ""hi""",5\n'),
            [{"name": 'He said "hi"', "age": 5}],
        )

    def test_age_bounds_are_inclusive(self):
        self.assertEqual(
            read_people("name,age\nA,0\nB,130\n"),
            [{"name": "A", "age": 0}, {"name": "B", "age": 130}],
        )

    def test_leading_zeros_are_ascii_digits(self):
        self.assertEqual(read_people("name,age\nA,007\n"), [{"name": "A", "age": 7}])

    def test_rejects_invalid_ages(self):
        for age in ["131", "999", "-1", "+5", " 5", "5 ", "", "1.5", "abc", "1e2", "٣"]:
            with self.subTest(age=age):
                with self.assertRaises(ValueError):
                    read_people(f"name,age\nA,{age}\n")

    def test_rejects_wrong_header(self):
        for header in ["Name,age", "age,name", "name,Age", "name", "name,age,extra", ""]:
            with self.subTest(header=header):
                with self.assertRaises(ValueError):
                    read_people(f"{header}\nA,1\n")

    def test_rejects_missing_header(self):
        with self.assertRaises(ValueError):
            read_people("")

    def test_rejects_row_with_missing_column(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nBob\n")
        with self.assertRaises(ValueError):
            read_people("name,age\nBob,\n") if False else read_people("name,age\nBob\n")

    def test_rejects_row_with_extra_column(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nBob,3,extra\n")

    def test_rejects_blank_line_as_malformed_row(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nBob,3\n\nAl,4\n")

    def test_rejects_unterminated_quote(self):
        with self.assertRaises(ValueError):
            read_people('name,age\n"Bob,3\n')

    def test_rejects_text_after_closing_quote(self):
        with self.assertRaises(ValueError):
            read_people('name,age\n"Bob"x,3\n')

    def test_rejects_nul_character(self):
        with self.assertRaises(ValueError):
            read_people("name,age\nBo\x00b,3\n")


if __name__ == "__main__":
    unittest.main()

