async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (requested.has(cursor)) {
        throw new Error(`collectPages: cursor requested twice: ${String(cursor)}`);
      }
      requested.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

module.exports = { collectPages };

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { collectPages } = require('../src/solution.cjs');

function scripted(pages) {
  const calls = [];
  const fetchPage = async (cursor) => {
    calls.push(cursor);
    const key = cursor === null ? 'null' : `s:${cursor}`;
    if (!(key in pages)) throw new Error(`unexpected cursor ${key}`);
    const page = pages[key];
    if (page instanceof Error) throw page;
    return page;
  };
  return { fetchPage, calls };
}

test('single page with next null returns its items', async () => {
  const { fetchPage, calls } = scripted({
    null: { items: [1, 2], next: null },
  });
  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
  assert.deepEqual(calls, [null]);
});

test('appends items from every page in order, keeping duplicates', async () => {
  const { fetchPage, calls } = scripted({
    null: { items: ['a', 'b'], next: 'c1' },
    's:c1': { items: ['b', 'c'], next: 'c2' },
    's:c2': { items: ['a'], next: null },
  });
  assert.deepEqual(await collectPages(fetchPage), ['a', 'b', 'b', 'c', 'a']);
  assert.deepEqual(calls, [null, 'c1', 'c2']);
});

test('an empty intermediate page does not stop collection', async () => {
  const { fetchPage } = scripted({
    null: { items: [1], next: 'c1' },
    's:c1': { items: [], next: 'c2' },
    's:c2': { items: [2], next: null },
  });
  assert.deepEqual(await collectPages(fetchPage), [1, 2]);
});

test('an empty-string cursor is a valid cursor, not end of pages', async () => {
  const { fetchPage, calls } = scripted({
    null: { items: ['x'], next: '' },
    's:': { items: ['y'], next: null },
  });
  assert.deepEqual(await collectPages(fetchPage), ['x', 'y']);
  assert.deepEqual(calls, [null, '']);
});

test('a repeated non-null cursor throws instead of looping', async () => {
  const { fetchPage, calls } = scripted({
    null: { items: [1], next: 'a' },
    's:a': { items: [2], next: 'b' },
    's:b': { items: [3], next: 'a' },
  });
  await assert.rejects(collectPages(fetchPage), /cursor requested twice: a/);
  assert.deepEqual(calls, [null, 'a', 'b']);
});

test('a cursor of null is only ever requested once, first', async () => {
  const { fetchPage } = scripted({
    null: { items: [1], next: '' },
    's:': { items: [2], next: '' },
  });
  await assert.rejects(collectPages(fetchPage), /cursor requested twice/);
});

test('a rejected fetch propagates its error', async () => {
  const boom = new Error('network down');
  const { fetchPage } = scripted({
    null: { items: [1], next: 'c1' },
    's:c1': boom,
  });
  await assert.rejects(collectPages(fetchPage), boom);
});

test('a synchronous throw from fetchPage on the first page propagates', async () => {
  const boom = new Error('bad first page');
  await assert.rejects(
