  );
});

async function collectPages(fetchPage) {
  const items = [];
  const requested = new Set();
  let cursor = null;

  for (;;) {
    if (cursor !== null) {
      if (requested.has(cursor)) {
        throw new Error(`cursor requested twice: ${JSON.stringify(cursor)}`);
      }
      requested.add(cursor);
    }

    const page = await fetchPage(cursor);
    for (const item of page.items) {
      items.push(item);
    }

    if (page.next === null) {
      return items;
    }
    cursor = page.next;
  }
}

