const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function assertSafeKeys(object, path) {
  for (const key of Object.getOwnPropertyNames(object)) {
    if (UNSAFE_KEYS.has(key)) throw new TypeError(`Unsafe key "${key}" at ${path}`);
  }
}

function assertJsonLike(value, path) {
  if (value === null || ['string', 'number', 'boolean', 'undefined'].includes(typeof value)) return;
  assertSafeKeys(value, path);
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) assertJsonLike(value[i], `${path}[${i}]`);
    return;
  }
  if (!isPlainObject(value)) throw new TypeError(`Unsupported value at ${path}`);
  for (const key of Object.keys(value)) assertJsonLike(value[key], `${path}.${key}`);
}

function deepCopy(value) {
  if (Array.isArray(value)) return value.map(deepCopy);
  if (!isPlainObject(value)) return value;
  const copy = {};
  for (const key of Object.keys(value)) copy[key] = deepCopy(value[key]);
  return copy;
}

function mergeValues(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return deepCopy(override);
  const result = {};
  for (const key of Object.keys(base)) {
    if (!hasOwn(override, key)) result[key] = deepCopy(base[key]);
  }
  for (const key of Object.keys(override)) {
    const baseValue = hasOwn(base, key) ? base[key] : undefined;
    result[key] = mergeValues(baseValue, override[key]);
  }
  return result;
}

function mergeConfig(base, override) {
  assertJsonLike(base, 'base');
  assertJsonLike(override, 'override');
  return mergeValues(base, override);
}

module.exports = { mergeConfig };

