'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function assertJsonLike(value, path) {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError(`${path} must be a finite number`);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index++) {
      assertJsonLike(value[index], `${path}[${index}]`);
    }
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.keys(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`${path} contains unsafe key "${key}"`);
      }
      assertJsonLike(value[key], `${path}.${key}`);
    }
    return;
  }
  throw new TypeError(`${path} is not a JSON-like value`);
}

function clone(value) {
  if (Array.isArray(value)) {
    return value.map((item) => clone(item));
  }
  if (value !== null && typeof value === 'object') {
    const copy = {};
    for (const key of Object.keys(value)) {
      copy[key] = clone(value[key]);
    }
    return copy;
  }
  return value;
}

function mergeValues(base, override) {
  if (isPlainObject(base) && isPlainObject(override)) {
    return mergeObjects(base, override);
  }
  return clone(override);
}

function mergeObjects(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = hasOwn(override, key)
      ? mergeValues(base[key], override[key])
      : clone(base[key]);
  }
  for (const key of Object.keys(override)) {
    if (!hasOwn(base, key)) {
      result[key] = clone(override[key]);
    }
  }
  return result;
}

function assertConfigObject(value, label) {
  if (!isPlainObject(value)) {
    throw new TypeError(`${label} must be a plain object`);
  }
  assertJsonLike(value, label);
}

function mergeConfig(base, override) {
  assertConfigObject(base, 'base');
  assertConfigObject(override, 'override');
  return mergeObjects(base, override);
}

module.exports = { mergeConfig };

