function withOwnKey(key, value, rest = {}) {
  const object = { ...rest };
  Object.defineProperty(object, key, {
    value,
    enumerable: true,
    writable: true,
    configurable: true,
  });
  return object;
}

function containers(value, found = new Set()) {
  if (value !== null && typeof value === 'object') {
    found.add(value);
    for (const item of Object.values(value)) {
      containers(item, found);
    }
  }
  return found;
}

