function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let sum = 0;
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    sum += weight;
    if (!Number.isSafeInteger(sum) || !Number.isSafeInteger(total * weight)) {
      throw new RangeError('total * weight and the weight sum must be safe integers');
    }
  }

  // BigInt keeps floor and remainder exact for products near the safe-integer limit.
  const bigTotal = BigInt(total);
  const bigSum = BigInt(sum);
  const shares = weights.map((weight) => {
    const product = bigTotal * BigInt(weight);
    return { cents: product / bigSum, remainder: product % bigSum };
  });

  let leftover = bigTotal;
  for (const share of shares) {
    leftover -= share.cents;
  }

  const order = shares.map((_, index) => index).sort((a, b) => {
    if (shares[a].remainder !== shares[b].remainder) {
      return shares[a].remainder > shares[b].remainder ? -1 : 1;
    }
    return a - b;
  });

  for (let k = 0; k < leftover; k += 1n) {
    shares[order[Number(k)]].cents += 1n;
  }

  return shares.map((share) => Number(share.cents));
}

