  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError("weights must be positive safe integers");
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum) || !Number.isSafeInteger(total * weight)) {
      throw new RangeError("total * weight and the weight sum must be safe integers");
    }
  }

  // BigInt keeps the quota floor and remainder exact for values near the safe limit.
  const bigTotal = BigInt(total);
  const bigSum = BigInt(weightSum);
  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0n;
  for (let i = 0; i < weights.length; i++) {
    const numerator = bigTotal * BigInt(weights[i]);
    shares[i] = numerator / bigSum;
    remainders[i] = numerator % bigSum;
    allocated += shares[i];
  }

  const leftover = Number(bigTotal - allocated);
  const order = Array.from({ length: weights.length }, (_, i) => i);
  order.sort((a, b) => {
    if (remainders[a] === remainders[b]) return a - b;
    return remainders[a] > remainders[b] ? -1 : 1;
  });
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1n;
  }

