function assertSafeNonNegativeInteger(value, name) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a nonnegative safe integer`);
  }
}

function validateWeights(weights) {
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError("weights must be a nonempty array");
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!Number.isSafeInteger(w) || w <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    sum += w;
    if (!Number.isSafeInteger(sum)) {
      throw new RangeError("sum of weights must be a safe integer");
    }
  }
  return sum;
}

function splitCents(total, weights) {
  assertSafeNonNegativeInteger(total, "total");
  const weightSum = validateWeights(weights);

  const shares = weights.map((w) => {
    const product = total * w;
    if (!Number.isSafeInteger(product)) {
      throw new RangeError("total * weight must be a safe integer");
    }
    const remainder = product % weightSum;
    return { quota: (product - remainder) / weightSum, remainder, index: 0 };
  });

  shares.forEach((share, i) => {
    share.index = i;
  });

  const allocated = shares.reduce((acc, s) => acc + s.quota, 0);
  let leftover = total - allocated;

  const byRemainder = [...shares].sort(
    (a, b) => b.remainder - a.remainder || a.index - b.index
  );
  for (let i = 0; leftover > 0; i++, leftover--) {
    shares[byRemainder[i].index].quota += 1;
  }

  return shares.map((s) => s.quota);
}

