const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  const t = BigInt(total);
  let weightSum = 0n;
  const products = [];
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    const w = BigInt(weight);
    weightSum += w;
    const product = t * w;
    if (product > MAX_SAFE) {
      throw new RangeError('total * weight exceeds the safe integer range');
    }
    products.push(product);
  }
  if (weightSum > MAX_SAFE) {
    throw new RangeError('sum of weights exceeds the safe integer range');
  }

  const allocations = [];
  const remainders = [];
  let allocated = 0n;
  for (const product of products) {
    const floor = product / weightSum;
    allocations.push(floor);
    remainders.push(product % weightSum);
    allocated += floor;
  }

  const leftover = Number(t - allocated);
  const order = allocations
    .map((_, index) => index)
    .sort((a, b) => {
      if (remainders[a] !== remainders[b]) {
        return remainders[a] > remainders[b] ? -1 : 1;
      }
      return a - b;
    });
  for (let k = 0; k < leftover; k++) {
    allocations[order[k]] += 1n;
  }

  return allocations.map(Number);
}

