'use strict';

function splitCents(total, weights) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }

  let weightSum = 0;
  for (let i = 0; i < weights.length; i++) {
    const weight = weights[i];
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      throw new RangeError(`weights[${i}] must be a positive safe integer`);
    }
    weightSum += weight;
    if (!Number.isSafeInteger(weightSum)) {
      throw new RangeError('sum of weights must be a safe integer');
    }
    if (!Number.isSafeInteger(total * weight)) {
      throw new RangeError(`total * weights[${i}] must be a safe integer`);
    }
  }

  const totalBig = BigInt(total);
  const weightSumBig = BigInt(weightSum);
  const shares = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0n;

  for (let i = 0; i < weights.length; i++) {
    const numerator = totalBig * BigInt(weights[i]);
    shares[i] = numerator / weightSumBig;
    remainders[i] = numerator % weightSumBig;
    allocated += shares[i];
  }

  const leftover = Number(totalBig - allocated);
  const order = weights.map((_, i) => i);
  order.sort((a, b) => {
    if (remainders[a] !== remainders[b]) {
      return remainders[a] > remainders[b] ? -1 : 1;
    }
    return a - b;
  });
  for (let k = 0; k < leftover; k++) {
    shares[order[k]] += 1n;
  }

  return shares.map(Number);
}

module.exports = { splitCents };

