def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    # datetime.fromisoformat rejects a trailing Z before Python 3.11
    normalized = text[:-1] + "+00:00" if text.endswith("Z") else text
    try:
        instant = datetime.fromisoformat(normalized)
    except ValueError:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from None
    if instant.tzinfo is None:
        raise ValueError(f"timestamp must include a UTC offset or Z: {text!r}")
    try:
        utc_instant = instant.astimezone(timezone.utc)
    except OverflowError:
        raise ValueError(f"timestamp is out of range: {text!r}") from None
    return datetime(utc_instant.year, utc_instant.month, utc_instant.day, tzinfo=timezone.utc)

