class Emitter {
  #events = new Map();

  on(event, fn) {
    let listeners = this.#events.get(event);
    if (!listeners) {
      listeners = new Map();
      this.#events.set(event, listeners);
    }

    let registration = listeners.get(fn);
    if (!registration) {
      registration = {};
      listeners.set(fn, registration);
    }

    return () => {
      if (listeners.get(fn) === registration) listeners.delete(fn);
    };
  }

  emit(event, value) {
    const listeners = this.#events.get(event);
    if (!listeners) return;

    for (const fn of [...listeners.keys()]) {
      fn(value);
    }
  }

  off(event, fn) {
    this.#events.get(event)?.delete(fn);
  }
}

