class Emitter {
  #events = new Map();

  on(event, fn) {
    let listeners = this.#events.get(event);
    if (!listeners) {
      listeners = new Map();
      this.#events.set(event, listeners);
    }
    // Already registered: this call did not create the registration, so its handle must not remove it.
    if (listeners.has(fn)) return () => {};

    const registration = {};
    listeners.set(fn, registration);
    return () => {
      if (this.#events.get(event)?.get(fn) === registration) this.off(event, fn);
    };
  }

  off(event, fn) {
    const listeners = this.#events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this.#events.delete(event);
  }

  emit(event, value) {
    const listeners = this.#events.get(event);
    if (!listeners) return;
    for (const fn of [...listeners.keys()]) fn(value);
  }
}

