'use strict';

class Emitter {
  #listeners = new Map();

  on(event, fn) {
    const records = this.#listeners.get(event) ?? [];
    if (records.some((record) => record.fn === fn)) {
      return () => {};
    }
    const record = { fn };
    this.#replace(event, [...records, record]);
    return () => this.#detach(event, record);
  }

  off(event, fn) {
    const records = this.#listeners.get(event) ?? [];
    this.#replace(event, records.filter((record) => record.fn !== fn));
  }

  emit(event, value) {
    for (const record of this.#listeners.get(event) ?? []) {
      record.fn(value);
    }
  }

  #detach(event, record) {
    const records = this.#listeners.get(event) ?? [];
    if (records.includes(record)) {
      this.#replace(event, records.filter((other) => other !== record));
    }
  }

  #replace(event, records) {
    if (records.length === 0) {
      this.#listeners.delete(event);
    } else {
      this.#listeners.set(event, records);
    }
  }
}

