import assert from "node:assert/strict";
import { mapResult, unwrapOr, type Result } from "../src/solution.ts";

function parseInteger(s: string): Result<number> {
  const n = Number(s);
  return s.trim() !== "" && Number.isInteger(n)
    ? { ok: true, value: n }
    : { ok: false, error: `not an integer: ${s}` };
}

describe("mapResult", () => {
  test("applies fn to the success value", () => {
    const result = mapResult({ ok: true, value: 2 }, (n) => n * 3);
    assert.deepEqual(result, { ok: true, value: 6 });
  });

  test("can change the value type", () => {
    const result = mapResult(parseInteger("7"), (n) => `#${n}`);
    assert.deepEqual(result, { ok: true, value: "#7" });
  });

  test("does not call fn on failure and returns the failure unchanged", () => {
    let calls = 0;
    const failure: Result<number> = { ok: false, error: "boom" };
    const result = mapResult(failure, (n) => {
      calls += 1;
      return n + 1;
    });
    assert.equal(calls, 0);
    assert.equal(result, failure);
  });

  test("failure passes through a chain of maps without calling any fn", () => {
    let calls = 0;
    const result = mapResult(
      mapResult(parseInteger("x"), (n) => {
        calls += 1;
        return n * 2;
      }),
      (n) => {
        calls += 1;
        return String(n);
      },
    );
    assert.equal(calls, 0);
    assert.deepEqual(result, { ok: false, error: "not an integer: x" });
  });

  test("exceptions thrown by fn propagate", () => {
    assert.throws(
      () =>
        mapResult({ ok: true, value: 1 }, () => {
          throw new Error("boom");
        }),
      { message: "boom" },
    );
  });
});

