  test("returns the value on success, ignoring fallback", () => {
    assert.equal(unwrapOr({ ok: true, value: 42 }, 0), 42);
  });

  test("returns falsy success values as-is", () => {
    assert.equal(unwrapOr({ ok: true, value: 0 }, 5), 0);
    assert.equal(unwrapOr({ ok: true, value: "" }, "fallback"), "");
  });

  test("returns fallback on failure", () => {
    assert.equal(unwrapOr({ ok: false, error: "nope" }, 5), 5);
  });
});

