  test("parse, transform, then unwrap", () => {
    const doubled = mapResult(parseInteger("21"), (n) => n * 2);
    assert.equal(unwrapOr(doubled, 0), 42);
  });

  test("failure skips the transform and unwrapOr supplies the fallback", () => {
    let calls = 0;
    const described = mapResult(parseInteger("abc"), (n) => {
      calls += 1;
      return `value is ${n}`;
    });
    assert.equal(calls, 0);
    assert.equal(unwrapOr(described, "unavailable"), "unavailable");
  });
});

