function lowerBound(numbers, target) {
  let lo = 0, hi = numbers.length - 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (numbers[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

module.exports = { lowerBound };

const test = require("node:test");
const assert = require("node:assert/strict");
const { lowerBound } = require("../src/solution.cjs");

test("empty input returns 0", () => {
  assert.equal(lowerBound([], 5), 0);
});

test("target greater than all elements returns length", () => {
  assert.equal(lowerBound([1, 2, 3], 4), 3);
  assert.equal(lowerBound([1], 2), 1);
});

test("target smaller than all elements returns 0", () => {
  assert.equal(lowerBound([1, 2, 3], 0), 0);
});

test("target present returns its index", () => {
  assert.equal(lowerBound([1, 3, 5, 7], 5), 2);
  assert.equal(lowerBound([1, 3, 5, 7], 1), 0);
  assert.equal(lowerBound([1, 3, 5, 7], 7), 3);
});

test("target between elements returns next larger index", () => {
  assert.equal(lowerBound([1, 3, 5, 7], 4), 2);
  assert.equal(lowerBound([1, 3, 5, 7], 6), 3);
});

test("duplicates return the first matching index", () => {
  assert.equal(lowerBound([2, 2, 2, 2], 2), 0);
  assert.equal(lowerBound([1, 2, 2, 2, 3], 2), 1);
  assert.equal(lowerBound([1, 1, 2, 2, 2, 3, 3], 3), 5);
  assert.equal(lowerBound([1, 1, 2, 2], 3), 4);
});

test("single element", () => {
  assert.equal(lowerBound([5], 5), 0);
  assert.equal(lowerBound([5], 4), 0);
  assert.equal(lowerBound([5], 6), 1);
});

test("negative numbers and non-integers", () => {
  assert.equal(lowerBound([-5, -1, 0, 2.5], -1), 1);
  assert.equal(lowerBound([-5, -1, 0, 2.5], 2.4), 3);
});

test("matches a linear reference on random inputs", () => {
  let seed = 12345;
  const rand = (n) => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed % n;
  };
  for (let trial = 0; trial < 500; trial++) {
    const len = rand(12);
    const arr = Array.from({ length: len }, () => rand(10)).sort((a, b) => a - b);
    const target = rand(12) - 1;
    const expected = arr.findIndex((x) => x >= target);
    assert.equal(
      lowerBound(arr, target),
      expected === -1 ? arr.length : expected,
      `arr=${JSON.stringify(arr)} target=${target}`
    );
