class ResolveUploadTests(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.base = Path(tmp.name).resolve()
        self.root = self.base / "root"
        self.sibling = self.base / "sibling"
        self.prefix_sibling = self.base / "root-evil"
        for directory in (self.root, self.sibling, self.prefix_sibling):
            directory.mkdir()
        (self.root / "inside.txt").write_text("ok")
        (self.sibling / "secret.txt").write_text("secret")

    def test_existing_file_inside_root(self):
        self.assertEqual(resolve_upload(self.root, "inside.txt"), self.root / "inside.txt")

    def test_nested_nonexistent_path_inside_root(self):
        self.assertEqual(
            resolve_upload(self.root, "a/b/new.txt"), self.root / "a" / "b" / "new.txt"
        )

    def test_does_not_create_files_or_directories(self):
        resolve_upload(self.root, "a/b/new.txt")
        self.assertFalse((self.root / "a").exists())

    def test_dotdot_that_stays_inside_root_is_allowed(self):
        self.assertEqual(
            resolve_upload(self.root, "a/../inside.txt"), self.root / "inside.txt"
        )

    def test_absolute_path_rejected(self):
        for supplied in (str(self.root / "inside.txt"), "/etc/passwd"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_root_itself_rejected(self):
        for supplied in ("", ".", "sub/.."):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_traversal_to_sibling_rejected(self):
        for supplied in ("../sibling/secret.txt", "../sibling/new.txt", "a/../../sibling/x"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_sibling_sharing_name_prefix_rejected(self):
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "../root-evil/x.txt")

    def test_symlink_to_file_outside_root_rejected(self):
        os.symlink(self.sibling / "secret.txt", self.root / "link.txt")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "link.txt")

    def test_path_through_symlink_to_outside_directory_rejected(self):
        os.symlink(self.sibling, self.root / "linkdir")
        for supplied in ("linkdir", "linkdir/secret.txt", "linkdir/new.txt"):
            with self.subTest(supplied=supplied):
                with self.assertRaises(ValueError):
                    resolve_upload(self.root, supplied)

    def test_dangling_symlink_to_outside_rejected(self):
        os.symlink(self.sibling / "not-yet.txt", self.root / "dangling")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "dangling")

    def test_dotdot_after_symlink_to_outside_rejected(self):
        os.symlink(self.sibling, self.root / "linkdir")
        with self.assertRaises(ValueError):
            resolve_upload(self.root, "linkdir/../inside.txt")

    def test_symlink_inside_root_allowed(self):
        (self.root / "real").mkdir()
        os.symlink(self.root / "real", self.root / "alias")
        self.assertEqual(
            resolve_upload(self.root, "alias/new.txt"), self.root / "real" / "new.txt"
